const CATS_M={1:'nonmetal',2:'noble',3:'alkali',4:'alkaline',5:'metalloid',6:'nonmetal',7:'nonmetal',8:'nonmetal',9:'halogen',10:'noble',11:'alkali',12:'alkaline',13:'posttrans',14:'metalloid',15:'nonmetal',16:'nonmetal',17:'halogen',18:'noble',19:'alkali',20:'alkaline',21:'transition',22:'transition',23:'transition',24:'transition',25:'transition',26:'transition',27:'transition',28:'transition',29:'transition',30:'transition',31:'posttrans',32:'metalloid',33:'metalloid',34:'nonmetal',35:'halogen',36:'noble',37:'alkali',38:'alkaline',39:'transition',40:'transition',41:'transition',42:'transition',43:'transition',44:'transition',45:'transition',46:'transition',47:'transition',48:'transition',49:'posttrans',50:'posttrans',51:'metalloid',52:'metalloid',53:'halogen',54:'noble',55:'alkali',56:'alkaline',57:'lanthanide',58:'lanthanide',59:'lanthanide',60:'lanthanide',61:'lanthanide',62:'lanthanide',63:'lanthanide',64:'lanthanide',65:'lanthanide',66:'lanthanide',67:'lanthanide',68:'lanthanide',69:'lanthanide',70:'lanthanide',71:'lanthanide',72:'transition',73:'transition',74:'transition',75:'transition',76:'transition',77:'transition',78:'transition',79:'transition',80:'transition',81:'posttrans',82:'posttrans',83:'posttrans',84:'metalloid',85:'halogen',86:'noble',87:'alkali',88:'alkaline',89:'actinide',90:'actinide',91:'actinide',92:'actinide',93:'actinide',94:'actinide',95:'actinide',96:'actinide',97:'actinide',98:'actinide',99:'actinide',100:'actinide',101:'actinide',102:'actinide',103:'actinide',104:'transition',105:'transition',106:'transition',107:'transition',108:'transition',109:'unknown',110:'unknown',111:'unknown',112:'transition',113:'unknown',114:'posttrans',115:'unknown',116:'unknown',117:'unknown',118:'noble'};
const PGM={1:[1,1],2:[1,18],3:[2,1],4:[2,2],5:[2,13],6:[2,14],7:[2,15],8:[2,16],9:[2,17],10:[2,18],11:[3,1],12:[3,2],13:[3,13],14:[3,14],15:[3,15],16:[3,16],17:[3,17],18:[3,18],19:[4,1],20:[4,2],21:[4,3],22:[4,4],23:[4,5],24:[4,6],25:[4,7],26:[4,8],27:[4,9],28:[4,10],29:[4,11],30:[4,12],31:[4,13],32:[4,14],33:[4,15],34:[4,16],35:[4,17],36:[4,18],37:[5,1],38:[5,2],39:[5,3],40:[5,4],41:[5,5],42:[5,6],43:[5,7],44:[5,8],45:[5,9],46:[5,10],47:[5,11],48:[5,12],49:[5,13],50:[5,14],51:[5,15],52:[5,16],53:[5,17],54:[5,18],55:[6,1],56:[6,2],57:[6,3],72:[6,4],73:[6,5],74:[6,6],75:[6,7],76:[6,8],77:[6,9],78:[6,10],79:[6,11],80:[6,12],81:[6,13],82:[6,14],83:[6,15],84:[6,16],85:[6,17],86:[6,18],87:[7,1],88:[7,2],89:[7,3],104:[7,4],105:[7,5],106:[7,6],107:[7,7],108:[7,8],109:[7,9],110:[7,10],111:[7,11],112:[7,12],113:[7,13],114:[7,14],115:[7,15],116:[7,16],117:[7,17],118:[7,18]};

const existing=new Set(EL_DATA.map(e=>e.n));
const FULL=[...EL_DATA];
for(let n=1;n<=118;n++){
  if(!existing.has(n)){
    const pg=PGM[n]||[7,null];
    // lanthanides 58-71 → p=6,g=null; actinides 89-103 → p=7,g=null
    const p2=n>=58&&n<=71?6:n>=89&&n<=103?7:pg[0];
    const g2=n>=58&&n<=71?null:n>=89&&n<=103?null:pg[1];
    FULL.push({n,s:ELEM_SYMS[n]||'?',ua:ELEM_NAMES[n]||'?',cat:CATS_M[n]||'unknown',mass:'—',state:'?',p:p2,g:g2,yr:'—',en:'-',levels:'—',val:'—',ox:'—',ion:'—',ionHint:'Дані уточнюються.',valHint:'Дані уточнюються.',desc:(ELEM_NAMES[n]||'?')+' ('+( ELEM_SYMS[n]||'?')+').'});
    existing.add(n);
  }
}
FULL.sort((a,b)=>a.n-b.n);
// Expose for global search
window._ELEMENTS = FULL.map(e=>({number:e.n, symbol:e.s, name:e.ua, category:e.cat}));
function openElementModal(e){ openModal(e.number); }

// ============ ТАБЛИЦЯ ============
let activeCat='all', searchQ='';
function isVis(e){const cOk=activeCat==='all'||e.cat===activeCat;const q=searchQ.toLowerCase();return cOk&&(!q||e.ua.toLowerCase().includes(q)||e.s.toLowerCase().includes(q)||String(e.n).includes(q));}
function elH(e){return `<div class="el cat-${e.cat}${isVis(e)?'':' dim'}" onclick="openModal(${e.n})" title="${e.ua}"><span class="en">${e.n}</span><span class="es">${e.s}</span><span class="enm">${e.ua}</span></div>`;}
function buildTable(){
  const byPos={};FULL.filter(e=>e.g).forEach(e=>{byPos[e.p+'-'+e.g]=e});
  let h='';
  for(let p=1;p<=7;p++){
    h+=`<div class="pl">${p}</div>`;
    for(let g=1;g<=18;g++){
      const e=byPos[p+'-'+g];
      if(e){h+=elH(e);}
      else if((p===6||p===7)&&g>=4&&g<=17){if(g===4)h+=`<div class="el emp lhole" style="grid-column:span 14"><span>${p===6?'57–71':'89–103'}</span></div>`;}
      else h+=`<div class="el emp"></div>`;
    }
  }
  document.getElementById('ptg').innerHTML=h;
  let lh='<div class="srl">Лан.</div>';FULL.filter(e=>e.cat==='lanthanide').forEach(e=>{lh+=elH(e)});document.getElementById('lanr').innerHTML=lh;
  let ah='<div class="srl">Акт.</div>';FULL.filter(e=>e.cat==='actinide').forEach(e=>{ah+=elH(e)});document.getElementById('actr').innerHTML=ah;
  document.getElementById('cnt').textContent=FULL.filter(isVis).length;
}
function fmtEconf(raw){
  if(!raw||raw==='—')return raw||'—';
  var tokens=raw.split(/(?=[1-7][spdf])/);
  return tokens.map(function(tok){var m=tok.match(/^([1-7])([spdf])(\d+)$/);return m?m[1]+m[2]+'<sup>'+m[3]+'</sup>':tok;}).join('');
}
function openModal(n){
  const e=FULL.find(x=>x.n===n);if(!e)return;
  const c=CC[e.cat]||'#78909C';const r=parseInt(c.slice(1,3),16),g2=parseInt(c.slice(3,5),16),b=parseInt(c.slice(5,7),16);

  // 1. Рамка і шапка — колір категорії
  const modal=document.querySelector('#overlay .modal');
  modal.style.borderColor=`rgba(${r},${g2},${b},0.35)`;

  const mhead=document.getElementById('mhead');
  mhead.innerHTML=`<div class="modal-el-card" style="background:rgba(${r},${g2},${b},0.12);border-color:rgba(${r},${g2},${b},0.35)"><span class="modal-el-num">${e.n}</span><span class="modal-el-sym" style="color:${c}">${e.s}</span><span class="modal-el-name">${e.ua}</span><span class="modal-el-mass">${e.mass} а.о.м.</span></div><div class="modal-head-info"><div class="modal-title">${e.ua} (${e.s})</div><div class="modal-cat-line" style="color:${c}">${CU[e.cat]||e.cat} · ${e.cat==='lanthanide'||e.cat==='actinide'?'f-блок':(e.g?e.g+' група':'—')} · ${e.p} період</div><div class="modal-desc">${e.desc}</div></div>`;
  mhead.style.borderBottomColor=`rgba(${r},${g2},${b},0.2)`;
  mhead.style.background=`rgba(${r},${g2},${b},0.06)`;

  const _oldBox=document.querySelector('.atom-canvas-box');if(_oldBox)_oldBox.remove();
  const _svgBox=document.createElement('div');_svgBox.className='atom-canvas-box';
  _svgBox.innerHTML='<svg id="atom-svg" viewBox="-130 -130 260 260"></svg><button class="atom-pause-btn" id="atom-pause-btn" onclick="toggleAtomPause()"><span id="atom-pause-icon">⏸</span><span id="atom-pause-label">Пауза</span></button>';
  mhead.insertAdjacentElement('afterend',_svgBox);if(window.renderAtomAnimation)window.renderAtomAnimation(e,document.getElementById('atom-svg'));

  // 2. Орбітальний тип
  const orbType=window.getOrbitalType?getOrbitalType(e):null;
  const orbLabels={circular:'s-орбіталь (коло)',dumbbell:'p-орбіталь (гантель)',clover4:'d-складова (конюшина)',rose8:'d-орбіталь (розетка)'};
  const orbHints={circular:'Сферична симетрія. Електрони рухаються по колу навколо ядра.',dumbbell:'Електрони рухаються вздовж гантелеподібних петель (вісімок). Визначає кути у молекулах.',clover4:'Наявність вакантних d-орбіталей дає 4-пелюсткову геометрію. Змінна валентність.',rose8:'Складна 8-пелюсткова геометрія d-підрівня. Змінна валентність, забарвлені сполуки.'};
  const orbTypeLabel=orbType?orbLabels[orbType]||orbType:'—';
  const orbTypeHint=orbType?orbHints[orbType]||'':'';

  // 3. Нові поля — температури
  const tMeltVal=e.tMelt!=null?e.tMelt+' К':'—';
  const tBoilVal=e.tBoil!=null?e.tBoil+' К':'—';
  const tempVal=(e.tMelt!=null||e.tBoil!=null)?(tMeltVal+' / '+tBoilVal):'—';

  // 4. Статус-бокс
  let statusText='';
  if(orbType){
    const outerCount=e.levels&&e.levels!=='—'?parseInt(e.levels.split(',').map(s=>s.trim()).filter(x=>x).pop()||'0'):0;
    const levelsKnown=e.levels&&e.levels!=='—';
    if(orbType==='circular'){
      if(e.g<=2&&(e.cat==='alkali'||e.cat==='alkaline')){
        const outerElCount=e.g===1?'зовнішній електрон':'два зовнішні електрони';
        const verb=e.g===1?'його легко відірвати':'їх легко відірвати';
        statusText=`⚡ Внутрішні орбіти швидкі, а ${outerElCount} на великому радіусі рухаються повільно — ${verb}, тому ${e.ua} активний метал.`;
      } else if(e.cat==='noble'||!levelsKnown){
        statusText=`⚡ Зовнішній рівень повністю заповнений — хімічно інертний елемент, не утворює сполук за звичайних умов.`;
      } else {
        const maxCap=e.g<=2?2:8;
        const holes=Math.max(0,maxCap-outerCount);
        statusText=`⚡ Компактний радіус дає високу швидкість електронів. ${holes>0?'Дірка обертається разом із шаром.':'Зовнішній рівень заповнений — не реагує.'}`;
      }
    } else if(orbType==='dumbbell'){
      const dHoles=Math.max(0,6-outerCount);
      const holesStr=dHoles===0?'Вільних місць немає':dHoles===1?'1 вакантне місце':''+dHoles+' вакантних місця';
      statusText=`💡 Внутрішня 1s-орбіта кругова. Зовнішні p-електрони рухаються вздовж гантелеподібних петель (вісімок). ${holesStr} — визначає валентність.`;
    } else if(orbType==='clover4'){
      const cHoles=Math.max(0,18-outerCount);
      statusText=`🍀 Наявність вакантних d-орбіталей створює 4-пелюсткову геометрію. ${cHoles>0?cHoles+' вакантних місця обертаються складним контуром. ':''} Змінна валентність завдяки розпаруванню електронів.`;
    } else if(orbType==='rose8'){
      const dMatches=e.econf?[...e.econf.matchAll(/(\d)d(\d+)/g)]:[];
      const lastD=dMatches.length?dMatches.reduce((a,b)=>parseInt(b[1])>parseInt(a[1])?b:a):null;
      const dCount=lastD?parseInt(lastD[2]):0;
      const outerS=outerCount;
      statusText=`💥 d-підрівень ${dCount===10?'повністю заповнений':'заповнюється'} (${dCount} e⁻ на 8-пелюстковій розетці)${outerS===1?', а 1 зовнішній електрон на s-орбіті рухається самотньо і повільно':outerS===2?', 2 зовнішні s-електрони на великій орбіті':''}.`;
    }
  }

  // 5. Побудова #mbody
  document.getElementById('mbody').innerHTML=
    // 1. Електронна конфігурація (wide)
    `<div class="mfield wide"><span class="mf-label">🔬 Електронна конфігурація</span><span class="mf-value" style="font-size:13px;letter-spacing:0.5px">${fmtEconf(e.econf)}</span><span class="mf-hint">Розподіл електронів по орбіталях. Визначає хімічні властивості.</span></div>`+
    // 2. Тип зовнішньої орбіталі (wide)
    (orbType?`<div class="mfield wide"><span class="mf-label">🌀 Тип зовнішньої орбіталі</span><span class="mf-value">${orbTypeLabel}</span><span class="mf-hint">${orbTypeHint}</span></div>`:'')+
    // 3. Електронні рівні
    `<div class="mfield"><span class="mf-label">⚡ Електронні рівні</span><span class="mf-value">${e.levels}</span><span class="mf-hint">Скільки електронів на кожній орбіті. <b>Останнє число</b> — зовнішній рівень, він визначає хімічні властивості.</span></div>`+
    // 4. Електронегативність
    `<div class="mfield"><span class="mf-label">🧲 Електронегативність</span><span class="mf-value">${e.en!=null&&e.en!=='-'?e.en:'—'}</span><span class="mf-hint">Шкала Полінга. Наскільки сильно атом <b>притягує електрони</b>. Найвища у Флуору — 3,98.</span></div>`+
    // 5. Валентність
    `<div class="mfield"><span class="mf-label">🔗 Валентність</span><span class="mf-value">${e.val}</span><span class="mf-hint">${e.valHint}</span></div>`+
    // 6. Ступені окиснення (wide)
    `<div class="mfield wide"><span class="mf-label">⚛️ Ступені окиснення</span><span class="mf-value">${e.ox}</span><span class="mf-hint">Скільки електронів елемент <b>віддає</b> (+) або <b>приймає</b> (−) у реакції. Потрібно для розстановки коефіцієнтів.</span></div>`+
    // 7. Заряд іона (wide)
    `<div class="mfield wide"><span class="mf-label">🔋 Заряд іона</span><span class="mf-value" style="color:${c}">${e.ion}</span><span class="mf-hint">${e.ionHint}</span></div>`+
    // 8. Агрегатний стан
    `<div class="mfield"><span class="mf-label">🌡️ Агрегатний стан</span><span class="mf-value">${SU[e.state]||e.state}</span><span class="mf-hint">При температурі 25°C і нормальному тиску.</span></div>`+
    // 9. Радіус атома
    `<div class="mfield"><span class="mf-label">📏 Радіус атома</span><span class="mf-value">${e.radius?e.radius+' пм':'—'}</span><span class="mf-hint">Ковалентний або ван-дер-ваальсовий радіус атома.</span></div>`+
    // 10. Енергія іонізації
    `<div class="mfield"><span class="mf-label">⚡ Енергія іонізації</span><span class="mf-value">${e.ionE?e.ionE+' кДж/моль':'—'}</span><span class="mf-hint">Мінімальна енергія, необхідна для відриву одного електрона від атома.</span></div>`+
    // 11. Густина
    `<div class="mfield"><span class="mf-label">📦 Густина</span><span class="mf-value">${e.density||'—'}</span><span class="mf-hint">При стандартних умовах (г/см³ для твердих і рідких, г/л для газів).</span></div>`+
    // 12. Т. плавлення / кипіння
    `<div class="mfield"><span class="mf-label">🔥 Т. плавлення / кипіння</span><span class="mf-value">${tempVal}</span><span class="mf-hint">Температури фазових переходів у Кельвінах.</span></div>`+
    // 13. Відкрито
    `<div class="mfield"><span class="mf-label">📅 Відкрито</span><span class="mf-value">${e.yr}</span><span class="mf-hint">Рік першого виділення або синтезу елемента.</span></div>`+
    // 14. Положення в таблиці (wide)
    `<div class="mfield wide"><span class="mf-label">📍 Положення в таблиці</span><span class="mf-value">${e.p} період · ${e.cat==='lanthanide'||e.cat==='actinide'?'f-блок':(e.g?e.g+' група':'—')}</span><span class="mf-hint"><b>Період</b> — горизонтальний рядок. <b>Група</b> — вертикальний стовпець. Номер групи підказує заряд іона для простих металів і неметалів.</span></div>`+
    // 15. Статус-бокс
    (statusText?`<div class="atom-status-box" style="border-left-color:rgba(${r},${g2},${b},0.6);background:rgba(${r},${g2},${b},0.08)">${statusText}</div>`:'');

  document.getElementById('overlay').classList.add('open');
}
function closeModal(e){if(e.target===document.getElementById('overlay'))closeModalDirect();}
function closeModalDirect(){
  if(window.stopAtomAnimation)window.stopAtomAnimation();
  const _b=document.querySelector('.atom-canvas-box');if(_b)_b.remove();
  document.querySelector('#overlay .modal').style.borderColor='';
  document.getElementById('mhead').style.background='';
  document.getElementById('overlay').classList.remove('open');
}
function toggleAtomPause(){
  const icon=document.getElementById('atom-pause-icon');
  const label=document.getElementById('atom-pause-label');
  if(window.isAnimationPaused&&window.isAnimationPaused()){
    if(window.resumeAtomAnimation)window.resumeAtomAnimation();
    if(icon)icon.textContent='⏸';if(label)label.textContent='Пауза';
  } else {
    if(window.pauseAtomAnimation)window.pauseAtomAnimation();
    if(icon)icon.textContent='▶';if(label)label.textContent='Грати';
  }
}
function setCat(cat,btn){activeCat=cat;document.querySelectorAll('.fb').forEach(b=>b.classList.remove('on'));btn.classList.add('on');buildTable();}
function doFilter(){searchQ=document.getElementById('srch').value;buildTable();}
